1: #!/bin/sh
2: # Verify the pinned portable UI source and emit a build artifact. This helper
3: # never installs dashboard files or writes to the external UI checkout.
4: set -eu
5: 
6: SCRIPT_DIR=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
7: SOURCE_ARCHIVE="$SCRIPT_DIR/source.tar.gz"
8: OUTPUT_DIR=target/ui-artifacts/3tched-json-render-ui
9: NPM_CACHE=${NPM_CACHE:-/var/cache/op-dbus-build/npm}
10: VERIFY_ONLY=0
11: 
12: usage() {
13:     cat <<'EOF'
14: Usage: vendor/3tched-json-render-ui/build-assets.sh [options]
15:   --source-archive PATH  source archive to verify (default: pinned archive)
16:   --output-dir PATH      artifact directory
17:   --npm-cache PATH       npm download cache
18:   --verify-only          verify provenance and contents without npm/build
19: EOF
20: }
21: 
22: while [ "$#" -gt 0 ]; do
23:     case "$1" in
24:         --source-archive) SOURCE_ARCHIVE=$2; shift 2 ;;
25:         --output-dir) OUTPUT_DIR=$2; shift 2 ;;
26:         --npm-cache) NPM_CACHE=$2; shift 2 ;;
27:         --verify-only) VERIFY_ONLY=1; shift ;;
28:         -h|--help) usage; exit 0 ;;
29:         *) printf 'unknown option: %s\n' "$1" >&2; usage >&2; exit 2 ;;
30:     esac
31: done
32: 
33: case "$OUTPUT_DIR" in
34:     /*) ;;
35:     *) OUTPUT_DIR=$(pwd)/$OUTPUT_DIR ;;
36: esac
37: case "$NPM_CACHE" in
38:     /*) ;;
39:     *) NPM_CACHE=$(pwd)/$NPM_CACHE ;;
40: esac
41: 
42: for command in awk find gzip jq npm node sed sha256sum tar wc; do
43:     command -v "$command" >/dev/null 2>&1 || {
44:         printf 'required command is unavailable: %s\n' "$command" >&2
45:         exit 1
46:     }
47: done
48: [ -f "$SOURCE_ARCHIVE" ] || { printf 'source archive is absent: %s\n' "$SOURCE_ARCHIVE" >&2; exit 1; }
49: [ -f "$SCRIPT_DIR/source.pin" ] || { printf 'source pin is absent\n' >&2; exit 1; }
50: [ -f "$SCRIPT_DIR/source-sha256sums" ] || { printf 'source manifest is absent\n' >&2; exit 1; }
51: 
52: pin() {
53:     key=$1
54:     sed -n "s/^${key}=//p" "$SCRIPT_DIR/source.pin"
55: }
56: 
57: [ "$(pin format)" = opdbus.3tched-json-render-ui-source.v1 ] || {
58:     printf 'unsupported UI source pin format\n' >&2
59:     exit 1
60: }

