1: /**
2:  * The doorbell: a content-free wake from the broker, gated by the identity
3:  * sled, telling this page to re-read its private state through the door.
4:  *
5:  * What the broker sees: an MQTT client whose id is the page's owner key
6:  * (`sha256(principal, session, genesis)`, handed out by the door), a password
7:  * that is the page's own door credential (`oia1:<base64>` or `sid1:…`), one
8:  * SUBSCRIBE to `opdbus/wake/<owner-key>`, and `{"seq": n}` messages. Nothing
9:  * authoritative and no identity ever transits the broker; the door verifies
10:  * the credential against the sled exactly as it does for a gRPC call.
11:  *
12:  * This is a deliberately minimal MQTT 3.1.1 client (CONNECT, SUBSCRIBE,
13:  * PUBLISH in, PINGREQ, DISCONNECT) over a WebSocket — about the size of a
14:  * dependency's type definitions, and fully testable with a fake socket.
15:  */
16: 
17: export interface DoorbellConfig {
18:   /** wss://host:port */
19:   listener: string;
20:   /** Owner key; doubles as the MQTT client id. */
21:   ownerKey: string;
22:   /** Exactly the topic the door said; the broker refuses anything else. */
23:   topic: string;
24:   /**
25:    * A fresh credential for each CONNECT. An issued OIA1 is one-time (the
26:    * door consumes its nonce), so a reconnect must not reuse the last one.
27:    */
28:   credential: () => Promise<string>;
29:   onWake: (seq: number) => void;
30:   onStatus?: (status: DoorbellStatus) => void;
31:   /** Keepalive in seconds (MQTT). */
32:   keepAliveSeconds?: number;
