                "cognitive state is bridge-owned and read-only; invoke a declared cognitive tool method instead"
                    .to_string()
            })
            .into_iter()
            .collect::<Vec<_>>();
        Ok(ApplyResult {
            success: errors.is_empty(),
            changes_applied: Vec::new(),
            errors,
            checkpoint: None,
        })

