29: /// Reading an absent optional argument used to panic the tokio worker and reset the
30: /// client connection, which surfaced as an empty HTTP response rather than an error.
31: pub(crate) fn field<'a>(input: &'a Value, key: &str) -> &'a Value {
32:     static NULL: std::sync::OnceLock<Value> = std::sync::OnceLock::new();
33:     input
34:         .get(key)
35:         .unwrap_or_else(|| NULL.get_or_init(|| json!(null)))
